const getActiveSwatchPillProps = (
  hex: string,
  fallbackHex = '#FF8A00'
): { className: string; style: React.CSSProperties } => {
  const cleanHex = hex && hex.startsWith('#') ? hex : fallbackHex;
  const useLightText = cleanHex.startsWith('#') ? isHexDark(cleanHex) : true;
  return {
    className:
      'font-extrabold ring-2 ring-[#111317] ring-offset-1 shadow-sm scale-[1.03]',
    style: {
      backgroundColor: cleanHex,
      borderColor: cleanHex,
      color: useLightText ? '#FFFFFF' : '#111317'
    }
  };
};

