// Plane Crash.ttf maps uppercase letters to wingding paint splatters; always render lowercase clean text.
const toK9ssText = (input: string): string =>
  (input || '')
    .toLowerCase()
    .replace(/[\u2018\u2019]/g, "'")
    .replace(/[\u2013\u2014]/g, '-')
    .replace(/["\u201C\u201D™®]/g, '')
    .replace(/\s+/g, ' ')
    .trim();

const formatLayerText = (text: string, font: FontKind): string =>
  font === 'k9ss' ? toK9ssText(text) : text;

const getSlideProduct = (slide: SlideState): ProductShowcaseItem => {
  const isK9 = slide.preset.startsWith('k9ss-') || slide.brandTheme === 'k9ss';
  if (slide.productId) {
    const byId = BRAND_PRODUCT_CATALOG.find((p) => p.id === slide.productId);
    if (byId) return byId;
  }
  if (slide.photoSrc) {
    const bySrc = BRAND_PRODUCT_CATALOG.find((p) => p.imageSrc === slide.photoSrc);
    if (bySrc) return bySrc;
  }
  return (
    BRAND_PRODUCT_CATALOG.find((p) => p.brandTheme === (isK9 ? 'k9ss' : 'raw-and-paw')) ||
    BRAND_PRODUCT_CATALOG[0]
  );
};

