const resolveSlideProducts = (
  slide: SlideState,
  fallbackProductId?: string
): ProductShowcaseItem[] => {
  const seen = new Set<string>();
  const resolved: ProductShowcaseItem[] = [];
  const addProd = (prod?: ProductShowcaseItem) => {
    if (!prod || seen.has(prod.id)) return;
    seen.add(prod.id);
    resolved.push(prod);
  };

  if (slide.preset !== 'no-photo' && slide.photoSrc && !slide.videoSrc) {
    const idMatch = slide.productId
      ? BRAND_PRODUCT_CATALOG.find((p) => p.id === slide.productId && p.imageSrc === slide.photoSrc)
      : undefined;
    addProd(idMatch || BRAND_PRODUCT_CATALOG.find((p) => p.imageSrc === slide.photoSrc));
  }

  for (const overlay of slide.photoOverlays || []) {
    if (overlay.visible === false) continue;
    addProd(BRAND_PRODUCT_CATALOG.find((p) => p.imageSrc === overlay.src));
  }

  if (resolved.length > 0) return resolved;

  const isStageBrandLogo = Boolean(
    slide.photoSrc && BRAND_LOGO_ASSETS.some((l) => l.src === slide.photoSrc)
  );
  const isPureTopicMode =
    slide.slideMode === 'info' ||
    slide.slideMode === 'customers' ||
    slide.slideMode === 'standards' ||
    slide.slideMode === 'didyouknow';

  if (!isStageBrandLogo && (!isPureTopicMode || Boolean(slide.productId))) {
    if (slide.productId) {
      addProd(BRAND_PRODUCT_CATALOG.find((p) => p.id === slide.productId));
    }
    if (resolved.length === 0 && !isPureTopicMode && fallbackProductId) {
      addProd(BRAND_PRODUCT_CATALOG.find((p) => p.id === fallbackProductId));
    }
  }

  return resolved;
};

const BRAND_LOGO_URLS = BRAND_LOGO_ASSETS.map((l) => l.src);

const BRAND_LOGO_CACHE = new Map<string, HTMLImageElement>();
let brandLogosPromise: Promise<void> | null = null;

const preloadBrandLogos = (): Promise<void> => {
  if (brandLogosPromise) return brandLogosPromise;
  brandLogosPromise = Promise.all(
    BRAND_LOGO_URLS.map(
      (url) =>
        new Promise<void>((resolve) => {
          if (BRAND_LOGO_CACHE.has(url)) {
            resolve();
            return;
          }
          const im = new Image();
          im.onload = () => {
            BRAND_LOGO_CACHE.set(url, im);
            resolve();
          };
          im.onerror = () => resolve();
          im.src = url;
        })
    )
  ).then(() => undefined);
  return brandLogosPromise;
};

const getCanvasFontSpec = (font: FontKind, fontSize: number): string =>
  font === 'k9ss'
    ? `400 ${fontSize}px 'Plane Crash', sans-serif`
    : font === 'condensed'
      ? `800 ${fontSize}px 'Barlow Condensed', 'DM Sans', sans-serif`
      : font === 'serif'
        ? `700 ${fontSize}px 'Playfair Display', serif`
        : font === 'serif-italic'
          ? `italic 600 ${fontSize}px 'Playfair Display', serif`
          : `800 ${fontSize}px 'DM Sans', sans-serif`;

const getDomFontStyle = (font: FontKind) => ({
  fontFamily:
    font === 'k9ss'
      ? "'Plane Crash', sans-serif"
      : font === 'condensed'
        ? "'Barlow Condensed', 'DM Sans', sans-serif"
        : font === 'sans'
          ? "'DM Sans', sans-serif"
          : "'Playfair Display', serif",
  fontStyle: font === 'serif-italic' ? ('italic' as const) : ('normal' as const),
  fontWeight:
    font === 'k9ss'
      ? 400
      : font === 'serif-italic'
        ? 600
        : font === 'serif'
          ? 700
          : 800,
  letterSpacing:
    font === 'k9ss'
      ? '0.04em'
      : font === 'condensed'
        ? '0.03em'
        : undefined,
  textTransform: font === 'k9ss' ? ('lowercase' as const) : undefined
});

