const resolvePillAppearance = (layer: TextLayer) => {
  const pal = PILL_PALETTE[layer.pill] || PILL_PALETTE.cream;
  if (layer.customPillColor && pal.hasBg) {
    const dark = isHexDark(layer.customPillColor);
    return {
      ...pal,
      bg: layer.customPillColor,
      border: layer.customPillColor,
      text: dark ? '#FFFFFF' : '#1C2621'
    };
  }
  return pal;
};

const applyColorAlpha = (color: string, opacity?: number): string => {
  if (opacity === undefined || opacity >= 0.999) return color;
  if (!color || color === 'transparent') return 'transparent';
  const alpha = Math.max(0, Math.min(1, opacity));
  const rgbaMatch = color.match(/^rgba?\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)(?:\s*,\s*([\d.]+))?\s*\)$/i);
  if (rgbaMatch) {
    const baseA = rgbaMatch[4] !== undefined ? parseFloat(rgbaMatch[4]) : 1;
    return `rgba(${rgbaMatch[1]}, ${rgbaMatch[2]}, ${rgbaMatch[3]}, ${(baseA * alpha).toFixed(3)})`;
  }
  const hex = color.replace('#', '').trim();
  if (hex.length === 3) {
    const r = parseInt(hex[0] + hex[0], 16);
    const g = parseInt(hex[1] + hex[1], 16);
    const b = parseInt(hex[2] + hex[2], 16);
    return `rgba(${r}, ${g}, ${b}, ${alpha.toFixed(3)})`;
  }
  if (hex.length === 6) {
    const r = parseInt(hex.slice(0, 2), 16);
    const g = parseInt(hex.slice(2, 4), 16);
    const b = parseInt(hex.slice(4, 6), 16);
    return `rgba(${r}, ${g}, ${b}, ${alpha.toFixed(3)})`;
  }
  return color;
};

const PHOTO_WINDOW_Z = 6;

const parseColorHexAndAlpha = (
  color: string | undefined,
  fallbackHex = '#FFFFFF'
): { hex: string; alpha: number } => {
  if (!color || color === 'transparent') return { hex: fallbackHex, alpha: 1 };
  const rgbaMatch = color.match(
    /^rgba?\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)(?:\s*,\s*([\d.]+))?\s*\)$/i
  );
  if (rgbaMatch) {
    const toHex = (n: string) =>
      Math.max(0, Math.min(255, parseInt(n, 10) || 0))
        .toString(16)
        .padStart(2, '0')
        .toUpperCase();
    const hex = `#${toHex(rgbaMatch[1])}${toHex(rgbaMatch[2])}${toHex(rgbaMatch[3])}`;
    const alpha =
      rgbaMatch[4] !== undefined ? Math.max(0, Math.min(1, parseFloat(rgbaMatch[4]))) : 1;
    return { hex, alpha };
  }
  if (color.startsWith('#')) {
    const clean = color.replace('#', '').trim();
    const full =
      clean.length === 3 ? clean.split('').map((c) => c + c).join('') : clean.slice(0, 6);
    if (/^[0-9a-f]{6}$/i.test(full)) {
      return { hex: `#${full.toUpperCase()}`, alpha: 1 };
    }
  }
  return { hex: fallbackHex, alpha: 1 };
};

const isWatermarkLayer = (layer: Pick<TextLayer, 'id' | 'label'>): boolean =>
  layer.id === 'tpl-watermark' ||
  layer.id.startsWith('watermark-') ||
  /watermark/i.test(layer.label || '');

const resolveLayerTextOpacity = (layer: TextLayer): number => {
  if (layer.textOpacity !== undefined) {
    return Math.max(0, Math.min(1, layer.textOpacity));
  }
  if (layer.textColor && /^rgba\(/i.test(layer.textColor)) {
    return parseColorHexAndAlpha(layer.textColor).alpha;
  }
  return 1;
};

const isBehindPhotoZ = (z: number | undefined, preset: FramePreset, defaultZ = 10): boolean =>
  preset !== 'no-photo' && preset !== 'minimal' && (z ?? defaultZ) < PHOTO_WINDOW_Z;

/** Resolve built-in brand family for built-in and custom saved brand themes. */
const getEffectiveBrandFamily = (kit: BrandThemeKit): BuiltInBrandThemeId => {
  if (
    kit.baseBrandId === 'sunlit-garden' ||
    kit.baseBrandId === 'raw-and-paw' ||
    kit.baseBrandId === 'k9ss'
  ) {
    return kit.baseBrandId;
  }
  if (kit.id === 'raw-and-paw' || kit.id === 'k9ss' || kit.id === 'sunlit-garden') {
    return kit.id;
  }
  const templates = kit.featuredTemplates || [];
  if (templates.some((t) => t.startsWith('k9ss-'))) return 'k9ss';
  if (templates.some((t) => t.startsWith('rp-'))) return 'raw-and-paw';
  const signature = `${kit.name} ${kit.shortName} ${kit.handle} ${kit.contactText}`.toLowerCase();
  if (signature.includes('k9ss') || signature.includes('k9 super')) return 'k9ss';
  if (signature.includes('raw') || signature.includes('paw')) return 'raw-and-paw';
  return 'sunlit-garden';
};

