const extractAge = (dog: DogRecord): string => {
  const m = (dog.description || '').match(/(\d+)-(month|week)-old/i);
  if (m) {
    const num = Number(m[1]);
    const unit = m[2].charAt(0).toUpperCase() + m[2].slice(1).toLowerCase() + (num === 1 ? '' : 's');
    return `${num} ${unit} Old`;
  }
  if (dog.name === 'Alex') return '4 Months Old';
  return '';
};

const getCanvasHeight = (r: CanvasRatio) => (r === 'story' ? 1920 : r === 'square' ? 1080 : 1350);

const roundRectPath = (
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  w: number,
  h: number,
  tl: number,
  tr: number,
  br: number,
  bl: number
) => {
  const maxR = Math.min(w / 2, h / 2);
  const rtl = Math.min(tl, maxR);
  const rtr = Math.min(tr, maxR);
  const rbr = Math.min(br, maxR);
  const rbl = Math.min(bl, maxR);
  ctx.beginPath();
  ctx.moveTo(x + rtl, y);
  ctx.lineTo(x + w - rtr, y);
  ctx.quadraticCurveTo(x + w, y, x + w, y + rtr);
  ctx.lineTo(x + w, y + h - rbr);
  ctx.quadraticCurveTo(x + w, y + h, x + w - rbr, y + h);
  ctx.lineTo(x + rbl, y + h);
  ctx.quadraticCurveTo(x, y + h, x, y + h - rbl);
  ctx.lineTo(x, y + rtl);
  ctx.quadraticCurveTo(x, y, x + rtl, y);
  ctx.closePath();
};

const chamferRectPath = (
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  w: number,
  h: number,
  cut: number
) => {
  const c = Math.max(0, Math.min(cut, w / 2, h / 2));
  ctx.beginPath();
  ctx.moveTo(x + c, y);
  ctx.lineTo(x + w - c, y);
  ctx.lineTo(x + w, y + c);
  ctx.lineTo(x + w, y + h - c);
  ctx.lineTo(x + w - c, y + h);
  ctx.lineTo(x + c, y + h);
  ctx.lineTo(x, y + h - c);
  ctx.lineTo(x, y + c);
  ctx.closePath();
};

const wrapLines = (ctx: CanvasRenderingContext2D, text: string, maxW: number): string[] => {
  const paragraphs = text.split('\n');
  const allLines: string[] = [];
  for (const para of paragraphs) {
    const words = para.trim().split(/\s+/).filter(Boolean);
    if (words.length === 0) {
      allLines.push('');
      continue;
    }
    let line = '';
    for (const word of words) {
      const test = line ? `${line} ${word}` : word;
      if (ctx.measureText(test).width > maxW && line) {
        allLines.push(line);
        line = word;
      } else {
        line = test;
      }
    }
    if (line) allLines.push(line);
  }
  return allLines.length > 0 ? allLines : [''];
};

const TEXT_BOX_STYLE_OPTIONS: Array<{ id: TextBoxStyle; label: string; hint: string }> = [
  { id: 'pill', label: '💊 Pill', hint: 'Rounded badge' },
  { id: 'tag', label: '🏷️ Tag', hint: 'Sharp editorial tag' },
  { id: 'outline', label: '▫️ Outline', hint: 'Clean 2.5px frame' },
  { id: 'underline', label: '━ Underline', hint: 'Accent bottom rule' },
  { id: 'left-bar', label: '▎ Left Bar', hint: 'Side accent callout' },
  { id: 'brutalist', label: '⬛ Brutalist', hint: 'Sharp block + shadow' },
  { id: 'glass', label: '🧊 Glass', hint: 'Frosted translucent bar' },
  { id: 'plain', label: 'T Plain', hint: 'Clean type, no box' }
];

const resolveEffectiveBoxStyle = (layer: TextLayer, preset?: FramePreset): TextBoxStyle => {
  if (layer.boxStyle) return layer.boxStyle;
  const pal = resolvePillAppearance(layer);
  if (!pal.hasBg) return 'plain';
  if (preset === 'k9ss-red-brutalist' && layer.id === 'tpl-badge') return 'brutalist';
  if (layer.pillRadius !== undefined && layer.pillRadius <= 8) return 'tag';
  return 'pill';
};

const getTextBoxVisualMetrics = (
  layer: TextLayer,
  pal: ReturnType<typeof resolvePillAppearance>,
  boxStyle: TextBoxStyle,
  preset?: FramePreset,
  multilineOrTall = false
) => {
  const pillOpacity = layer.pillOpacity !== undefined ? layer.pillOpacity : 1;
  const isBrutalist = boxStyle === 'brutalist';
  const isTag = boxStyle === 'tag';
  const isOutline = boxStyle === 'outline';
  const isUnderline = boxStyle === 'underline';
  const isLeftBar = boxStyle === 'left-bar';
  const isGlass = boxStyle === 'glass';
  const isPlain = boxStyle === 'plain';
  const isK9Brutalist =
    isBrutalist && (Boolean(preset?.startsWith('k9ss-')) || layer.id === 'tpl-badge');

  const padX = isLeftBar
    ? 22
    : isUnderline || isPlain
      ? 10
      : pal.hasBg || isOutline || isGlass || isTag || isBrutalist
        ? 26
        : 10;

  const defaultRadius = isBrutalist
    ? 0
    : isLeftBar
      ? 4
      : isUnderline || isPlain
        ? 0
        : isTag
          ? 8
          : isOutline
            ? 12
            : isGlass
              ? 14
              : multilineOrTall
                ? 32
                : 999;

  const r = layer.pillRadius !== undefined ? layer.pillRadius : defaultRadius;
  const hasFilledBg = boxStyle === 'pill' || isTag || isBrutalist || isGlass;
  const isTransparentBox = isPlain || isUnderline || isLeftBar || isOutline;

  const fallbackAccent =
    preset?.startsWith('k9ss-') ? '#D32F2F' : '#FF8A00';
  const accentColor =
    layer.customPillColor ||
    (pal.hasBg ? pal.bg : layer.textColor && isHexDark(layer.textColor) ? '#2E5A44' : fallbackAccent);

  const resolvedTextColor =
    layer.textColor ||
    (isTransparentBox
      ? !pal.hasBg
        ? pal.text
        : isHexDark(pal.bg)
          ? pal.bg
          : '#14161B'
      : isGlass && !pal.hasBg
        ? layer.pill === 'none-light'
          ? '#FFFFFF'
          : '#14161B'
        : pal.text);

  const resolvedBgHex = pal.hasBg
    ? pal.bg
    : isBrutalist || isTag || boxStyle === 'pill'
      ? '#FFFFFF'
      : isGlass
        ? resolvedTextColor === '#FFFFFF'
          ? '#12161E'
          : '#FFFFFF'
        : 'transparent';

  const resolvedBorderColor =
    isBrutalist && !layer.customPillColor && layer.pill === 'white'
      ? '#0E1014'
      : pal.hasBg
        ? pal.border
        : accentColor;

  return {
    boxStyle,
    pillOpacity,
    padX,
    r,
    hasFilledBg,
    isTransparentBox,
    isBrutalist,
    isK9Brutalist,
    isTag,
    isOutline,
    isUnderline,
    isLeftBar,
    isGlass,
    isPlain,
    accentColor,
    resolvedTextColor,
    resolvedBgHex,
    resolvedBorderColor
  };
};

/** Computes wrapped lines, box dimensions, and radius for both behind-photo watermarks and foreground text layers. */
const computeTextLayerLayout = (
  ctx: CanvasRenderingContext2D,
  layer: TextLayer,
  preset?: FramePreset
) => {
  const pal = resolvePillAppearance(layer);
  const boxStyle = resolveEffectiveBoxStyle(layer, preset);
  const align = layer.textAlign || 'center';
  const rawFormatted = formatLayerText(layer.text, layer.font);
  const hasSubline = Boolean(layer.sublineColor) && rawFormatted.includes('\n');
  const prelimVis = getTextBoxVisualMetrics(layer, pal, boxStyle, preset, layer.padY > 28);
  const padX = prelimVis.padX;
  const innerMaxW = Math.max(60, layer.pillWidth - padX * 2);

  if (hasSubline) {
    const nlIdx = rawFormatted.indexOf('\n');
    const headRaw = rawFormatted.slice(0, nlIdx);
    const subRaw = rawFormatted.slice(nlIdx + 1);
    const headSize = layer.fontSize;
    const headLineH = headSize * 1.12;
    const subSize = Math.max(11, Math.round(layer.fontSize * 0.58));
    const subLineH = subSize * 1.2;

    ctx.font = getCanvasFontSpec(layer.font, headSize);
    const headLines = wrapLines(ctx, headRaw, innerMaxW);
    ctx.font = getCanvasFontSpec(layer.font, subSize);
    const subLines = wrapLines(ctx, subRaw, innerMaxW);

    const innerH = headLines.length * headLineH + 4 + subLines.length * subLineH;
    const boxW = layer.pillWidth;
    const boxH = innerH + layer.padY * 2;
    const totalCount = headLines.length + subLines.length;
    const vis = getTextBoxVisualMetrics(
      layer,
      pal,
      boxStyle,
      preset,
      totalCount > 1 || layer.padY > 28
    );
    return {
      pal,
      vis,
      align,
      padX: vis.padX,
      hasSubline: true as const,
      headLines,
      subLines,
      headSize,
      headLineH,
      subSize,
      subLineH,
      innerH,
      boxW,
      boxH,
      r: vis.r
    };
  }

  const fontSize = layer.fontSize;
  ctx.font = getCanvasFontSpec(layer.font, fontSize);
  const textLines = wrapLines(ctx, rawFormatted, innerMaxW);
  const lineH = fontSize * 1.24;
  const boxW = layer.pillWidth;
  const boxH = textLines.length * lineH + layer.padY * 2;
  const vis = getTextBoxVisualMetrics(
    layer,
    pal,
    boxStyle,
    preset,
    textLines.length > 1 || layer.padY > 28
  );

  return {
    pal,
    vis,
    align,
    padX: vis.padX,
    hasSubline: false as const,
    textLines,
    fontSize,
    lineH,
    boxW,
    boxH,
    r: vis.r
  };
};

/** Draws a single TextLayer onto a 1080px export canvas with rotation, alignment, boxStyle, and optional subline styling. */
const drawTextLayerOnCanvas = (
  ctx: CanvasRenderingContext2D,
  layer: TextLayer,
  preset: FramePreset
) => {
  const m = computeTextLayerLayout(ctx, layer, preset);
  const { pal, vis, align, padX, boxW, boxH, r } = m;
  const bx = -boxW / 2;
  const by = -boxH / 2;
  const {
    pillOpacity,
    resolvedTextColor,
    resolvedBgHex,
    resolvedBorderColor,
    accentColor,
    isBrutalist,
    isK9Brutalist,
    isOutline,
    isUnderline,
    isLeftBar,
    isGlass,
    hasFilledBg
  } = vis;

  ctx.save();
  ctx.translate(layer.x, layer.y);
  if (layer.rotation) {
    ctx.rotate((layer.rotation * Math.PI) / 180);
  }

  if (hasFilledBg && pillOpacity > 0.01) {
    if (isBrutalist) {
      const hardShadowCol = isK9Brutalist ? '#D32F2F' : '#0E1014';
      roundRectPath(ctx, bx + 5, by + 5, boxW, boxH, r, r, r, r);
      ctx.fillStyle = applyColorAlpha(hardShadowCol, pillOpacity);
      ctx.fill();
    }
    ctx.save();
    if (!isBrutalist && pal.shadow && pillOpacity > 0.15) {
      ctx.shadowColor = `rgba(0,0,0,${(0.16 * pillOpacity).toFixed(3)})`;
      ctx.shadowBlur = isGlass ? 18 : 22;
      ctx.shadowOffsetY = isGlass ? 6 : 8;
    }
    const bgAlpha = isGlass ? Math.min(0.84, Math.max(0.32, pillOpacity * 0.72)) : pillOpacity;
    roundRectPath(ctx, bx, by, boxW, boxH, r, r, r, r);
    ctx.fillStyle = applyColorAlpha(resolvedBgHex, bgAlpha);
    ctx.fill();
    ctx.restore();

    roundRectPath(ctx, bx, by, boxW, boxH, r, r, r, r);
    ctx.strokeStyle = isGlass
      ? applyColorAlpha('#FFFFFF', Math.min(0.65, pillOpacity * 0.65))
      : applyColorAlpha(resolvedBorderColor, Math.min(1, pillOpacity * 1.15));
    ctx.lineWidth = isBrutalist ? 2.5 : 2;
    ctx.stroke();
  } else if (isOutline && pillOpacity > 0.01) {
    roundRectPath(ctx, bx, by, boxW, boxH, r, r, r, r);
    ctx.fillStyle = applyColorAlpha(accentColor, 0.08 * pillOpacity);
    ctx.fill();
    roundRectPath(ctx, bx, by, boxW, boxH, r, r, r, r);
    ctx.strokeStyle = applyColorAlpha(accentColor, Math.max(0.55, pillOpacity));
    ctx.lineWidth = 2.5;
    ctx.stroke();
  } else if (isLeftBar && pillOpacity > 0.01) {
    const washAlpha = isHexDark(resolvedTextColor) ? 0.07 : 0.16;
    roundRectPath(ctx, bx, by, boxW, boxH, r, r, r, r);
    ctx.fillStyle = applyColorAlpha(accentColor, washAlpha * pillOpacity);
    ctx.fill();
    roundRectPath(ctx, bx, by, 6, boxH, r, 0, 0, r);
    ctx.fillStyle = applyColorAlpha(accentColor, Math.max(0.75, pillOpacity));
    ctx.fill();
  } else if (isUnderline && pillOpacity > 0.01) {
    ctx.fillStyle = applyColorAlpha(accentColor, Math.max(0.75, pillOpacity));
    ctx.fillRect(bx, by + boxH - 4, boxW, 4);
  }

  if (
    !hasFilledBg &&
    !isOutline &&
    !isWatermarkLayer(layer) &&
    resolveLayerTextOpacity(layer) >= 0.45 &&
    (layer.zIndex ?? 10) >= PHOTO_WINDOW_Z &&
    (!isHexDark(resolvedTextColor) || pillOpacity < 0.35)
  ) {
    ctx.shadowColor = 'rgba(0,0,0,0.48)';
    ctx.shadowBlur = 16;
    ctx.shadowOffsetY = 4;
  }

  const textAlpha = resolveLayerTextOpacity(layer);
  const mainTextColor = applyColorAlpha(
    parseColorHexAndAlpha(resolvedTextColor, '#FFFFFF').hex,
    textAlpha
  );
  const subTextColor = layer.sublineColor
    ? applyColorAlpha(parseColorHexAndAlpha(layer.sublineColor, '#FFFFFF').hex, textAlpha)
    : mainTextColor;

  const textX =
    align === 'left' ? bx + padX : align === 'right' ? bx + boxW - padX : 0;
  ctx.textAlign = align;
  ctx.textBaseline = 'middle';

  if (m.hasSubline) {
    let curY = -m.innerH / 2;
    ctx.fillStyle = mainTextColor;
    ctx.font = getCanvasFontSpec(layer.font, m.headSize);
    for (const line of m.headLines) {
      ctx.fillText(line, textX, curY + m.headLineH / 2 + 1);
      curY += m.headLineH;
    }
    curY += 4;
    ctx.fillStyle = subTextColor;
    ctx.font = getCanvasFontSpec(layer.font, m.subSize);
    for (const line of m.subLines) {
      ctx.fillText(line, textX, curY + m.subLineH / 2 + 1);
      curY += m.subLineH;
    }
  } else {
    ctx.fillStyle = mainTextColor;
    ctx.font = getCanvasFontSpec(layer.font, m.fontSize);
    const totalH = (m.textLines.length - 1) * m.lineH;
    m.textLines.forEach((line, i) => {
      ctx.fillText(line, textX, -totalH / 2 + i * m.lineH + 2);
    });
  }

  ctx.restore();
};

const getLayerDomPresentation = (
  layer: TextLayer,
  preset: FramePreset,
  hideVisual = false
) => {
  const pal = resolvePillAppearance(layer);
  const boxStyle = resolveEffectiveBoxStyle(layer, preset);
  const multilineOrTall = layer.padY > 28 || layer.text.includes('\n');
  const vis = getTextBoxVisualMetrics(layer, pal, boxStyle, preset, multilineOrTall);

  if (hideVisual) {
    return {
      vis,
      pal,
      padX: vis.padX,
      resolvedRadius: vis.r,
      subTextColor: 'transparent',
      style: {
        boxSizing: 'border-box' as const,
        background: 'transparent',
        color: 'transparent',
        border: 'none',
        boxShadow: 'none',
        textShadow: 'none'
      }
    };
  }

  let background = 'transparent';
  let border = 'none';
  let borderLeft: string | undefined;
  let borderBottom: string | undefined;
  let backdropFilter: string | undefined;
  let boxShadow = 'none';

  if (vis.hasFilledBg && vis.pillOpacity > 0.01) {
    const bgAlpha = vis.isGlass
      ? Math.min(0.84, Math.max(0.32, vis.pillOpacity * 0.72))
      : vis.pillOpacity;
    background = applyColorAlpha(vis.resolvedBgHex, bgAlpha);
    border = vis.isGlass
      ? `1.5px solid ${applyColorAlpha('#FFFFFF', Math.min(0.65, vis.pillOpacity * 0.65))}`
      : `${vis.isBrutalist ? 2.5 : 2}px solid ${applyColorAlpha(
        vis.resolvedBorderColor,
        Math.min(1, vis.pillOpacity * 1.15)
      )}`;
    if (vis.isGlass) {
      backdropFilter = 'blur(10px)';
    }
    if (vis.isBrutalist) {
      boxShadow = `5px 5px 0px ${applyColorAlpha(
        vis.isK9Brutalist ? '#D32F2F' : '#0E1014',
        vis.pillOpacity
      )}`;
    } else if (pal.shadow && vis.pillOpacity > 0.15) {
      boxShadow = `0 10px 26px rgba(0,0,0,${(0.18 * vis.pillOpacity).toFixed(3)})`;
    }
  } else if (vis.isOutline && vis.pillOpacity > 0.01) {
    background = applyColorAlpha(vis.accentColor, 0.08 * vis.pillOpacity);
    border = `2.5px solid ${applyColorAlpha(vis.accentColor, Math.max(0.55, vis.pillOpacity))}`;
  } else if (vis.isLeftBar && vis.pillOpacity > 0.01) {
    const washAlpha = isHexDark(vis.resolvedTextColor) ? 0.07 : 0.16;
    background = applyColorAlpha(vis.accentColor, washAlpha * vis.pillOpacity);
    borderLeft = `6px solid ${applyColorAlpha(vis.accentColor, Math.max(0.75, vis.pillOpacity))}`;
  } else if (vis.isUnderline && vis.pillOpacity > 0.01) {
    borderBottom = `4px solid ${applyColorAlpha(vis.accentColor, Math.max(0.75, vis.pillOpacity))}`;
  }

  const textAlpha = resolveLayerTextOpacity(layer);
  const mainTextColor = applyColorAlpha(
    parseColorHexAndAlpha(vis.resolvedTextColor, '#FFFFFF').hex,
    textAlpha
  );
  const subTextColor = layer.sublineColor
    ? applyColorAlpha(parseColorHexAndAlpha(layer.sublineColor, '#FFFFFF').hex, textAlpha)
    : mainTextColor;

  const textShadow =
    !vis.hasFilledBg &&
      !vis.isOutline &&
      !isWatermarkLayer(layer) &&
      textAlpha >= 0.45 &&
      (layer.zIndex ?? 10) >= PHOTO_WINDOW_Z &&
      (!isHexDark(vis.resolvedTextColor) || vis.pillOpacity < 0.35)
      ? '0 4px 16px rgba(0,0,0,0.48)'
      : 'none';

  return {
    vis,
    pal,
    padX: vis.padX,
    resolvedRadius: vis.r,
    subTextColor,
    style: {
      boxSizing: 'border-box' as const,
      background,
      color: mainTextColor,
      border,
      ...(borderLeft ? { borderLeft } : {}),
      ...(borderBottom ? { borderBottom } : {}),
      ...(backdropFilter ? { backdropFilter, WebkitBackdropFilter: backdropFilter } : {}),
      boxShadow,
      textShadow
    }
  };
};

const loadImageElement = (src: string): Promise<HTMLImageElement | null> =>
  new Promise((resolve) => {
    if (!src) {
      resolve(null);
      return;
    }
    const img = new Image();
    if (/^https?:\/\//i.test(src)) img.crossOrigin = 'anonymous';
    img.onload = () => resolve(img);
    img.onerror = () => resolve(null);
    img.src = src;
  });

type DrawableMedia = HTMLImageElement | HTMLVideoElement;

const getDrawableDims = (m: DrawableMedia | null): { w: number; h: number } => {
  if (!m) return { w: 0, h: 0 };
  if (m instanceof HTMLVideoElement) {
    return { w: m.videoWidth, h: m.videoHeight };
  }
  return { w: m.naturalWidth, h: m.naturalHeight };
};

const loadVideoElement = (src: string, muted = true): Promise<HTMLVideoElement | null> =>
  new Promise((resolve) => {
    if (!src) {
      resolve(null);
      return;
    }
    const vid = document.createElement('video');
    if (/^https?:\/\//i.test(src)) vid.crossOrigin = 'anonymous';
    vid.muted = muted;
    vid.playsInline = true;
    vid.preload = 'auto';
    let settled = false;
    const finish = (res: HTMLVideoElement | null) => {
      if (settled) return;
      settled = true;
      vid.onloadeddata = null;
      vid.oncanplay = null;
      vid.onerror = null;
      resolve(res);
    };
    const onReady = () => {
      if (vid.videoWidth > 0) finish(vid);
    };
    vid.onloadeddata = onReady;
    vid.oncanplay = onReady;
    vid.onerror = () => finish(null);
    vid.src = src;
    vid.load();
    setTimeout(() => finish(vid.videoWidth > 0 ? vid : null), 8000);
  });

const compressImageFileToDataUrl = (file: File, maxDim = 1280, quality = 0.84): Promise<string> =>
  new Promise((resolve) => {
    const reader = new FileReader();
    reader.onerror = () => resolve('');
    reader.onload = (ev) => {
      const raw = typeof ev.target?.result === 'string' ? ev.target.result : '';
      if (!raw) {
        resolve('');
        return;
      }
      const img = new Image();
      img.onload = () => {
        try {
          const scale = Math.min(1, maxDim / Math.max(img.naturalWidth || 1, img.naturalHeight || 1));
          const w = Math.max(1, Math.round((img.naturalWidth || 1) * scale));
          const h = Math.max(1, Math.round((img.naturalHeight || 1) * scale));
          const canvas = document.createElement('canvas');
          canvas.width = w;
          canvas.height = h;
          const ctx = canvas.getContext('2d');
          if (!ctx) {
            resolve(raw);
            return;
          }
          ctx.drawImage(img, 0, 0, w, h);
          resolve(canvas.toDataURL('image/jpeg', quality));
        } catch {
          resolve(raw);
        }
      };
      img.onerror = () => resolve(raw);
      img.src = raw;
    };
    reader.readAsDataURL(file);
  });

