                        {OVERLAY_BORDER_SWATCHES.map((sw) => {
                          const isActive =
                            (selectedShapeBlock.strokeWidth ?? 0) > 0 &&
                            (selectedShapeBlock.strokeColor || '').toUpperCase() ===
                              sw.value.toUpperCase();
                          const activeProps = isActive
                            ? getActiveSwatchPillProps(sw.value)
                            : null;
                          return (
                            <button
                              key={`blk-stroke-${sw.value}`}
                              type="button"
                              onClick={() =>
                                updateShapeBlock(
                                  selectedShapeBlock.id,
                                  {
                                    strokeColor: sw.value,
                                    ...((selectedShapeBlock.strokeWidth ?? 0) <= 0
                                      ? { strokeWidth: 4 }
                                      : {})
                                  },
                                  true
                                )
                              }
                              style={activeProps ? activeProps.style : undefined}
                              className={`flex items-center gap-1.5 px-2.5 py-1 rounded-full border text-xs font-bold touch-manipulation cursor-pointer transition ${activeProps
                                  ? activeProps.className
                                  : 'bg-[#F6F4EE] border-[#DDD6C7] text-[#3E4D45] hover:bg-[#EFECE4]'
                                }`}
                            >
                              <span
                                className="w-3.5 h-3.5 rounded-full border border-black/20 shrink-0"
                                style={{ background: sw.value }}
                              />
                              <span>{sw.label}</span>
                            </button>
                          );
                        })}
